"""Parametric Acupoint Localization Rules for MSK-Therapy-OS.

Defines formal anatomical localization rules according to the WHO Standard
Acupuncture Point Locations in the Western Pacific Region (2008),
referenced to Foundational Model of Anatomy (FMA) concept identifiers
and canonical skeletal/topographic landmarks on BodyParts3D 4.0.
Pure-Python, zero external dependencies.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
import math
from typing import Any, Dict, List, Optional, Tuple

from msk_therapy_os.landmark_registry import LandmarkRegistry, CANONICAL_LANDMARKS, BodyRegion
from msk_therapy_os.cun_scaling import CunScalingEngine


class LocalizationMethod(str, Enum):
    B_CUN_PROPORTIONAL = "B_CUN_PROPORTIONAL"
    BONY_DEPRESSION = "BONY_DEPRESSION"
    TENDON_BORDER = "TENDON_BORDER"
    JOINT_DEPRESSION = "JOINT_DEPRESSION"
    SURFACE_TOPOGRAPHIC = "SURFACE_TOPOGRAPHIC"
    MUSCLE_BORDER = "MUSCLE_BORDER"
    LANDMARK_DEFINED = "LANDMARK_DEFINED"
    MIDLINE_REFERENCE = "MIDLINE_REFERENCE"
    PARASAGITTAL_LINE = "PARASAGITTAL_LINE"
    SKIN_CREASE = "SKIN_CREASE"
    TENDON_INTERVAL = "TENDON_INTERVAL"


@dataclass(frozen=True)
class AcupointLocalizationRule:
    point_code: str
    meridian_code: str
    name_en: str
    name_zh: str
    name_vi: str
    localization_method: LocalizationMethod
    fma_anchor: str
    body_region: BodyRegion
    who_reference: str
    skeletal_structure: str
    start_landmark_id: str
    end_landmark_id: str
    proportional_fraction: float
    lateral_offset_cun: float
    transverse_segment_id: Optional[str] = None
    tolerance_radius_mm: float = 3.0
    uncertainty_mm: float = 5.0
    quality_class: str = "CLASS_B"
    is_posture_sensitive: bool = False
    sensitive_joint: Optional[str] = None
    threshold_deg: float = 0.0
    surface_normal: Optional[Tuple[float, float, float]] = None

    def to_dict(self) -> Dict[str, Any]:
        return {
            "point_code": self.point_code,
            "meridian_code": self.meridian_code,
            "name_en": self.name_en,
            "name_zh": self.name_zh,
            "name_vi": self.name_vi,
            "localization_method": self.localization_method.value,
            "fma_anchor": self.fma_anchor,
            "body_region": self.body_region.value,
            "who_reference": self.who_reference,
            "skeletal_structure": self.skeletal_structure,
            "start_landmark_id": self.start_landmark_id,
            "end_landmark_id": self.end_landmark_id,
            "proportional_fraction": self.proportional_fraction,
            "lateral_offset_cun": self.lateral_offset_cun,
            "transverse_segment_id": self.transverse_segment_id,
            "tolerance_radius_mm": self.tolerance_radius_mm,
            "uncertainty_mm": self.uncertainty_mm,
            "quality_class": self.quality_class,
            "is_posture_sensitive": self.is_posture_sensitive,
            "sensitive_joint": self.sensitive_joint,
            "threshold_deg": self.threshold_deg,
            "surface_normal": self.surface_normal,
        }


