class AcupointLocalizationEngine:
    """Evaluates anatomical localization rules against BodyParts3D FJ2810 landmarks."""

    def __init__(self, landmark_registry: Optional[LandmarkRegistry] = None) -> None:
        self.registry = landmark_registry or LandmarkRegistry()
        self.cun_engine = CunScalingEngine(self.registry)
        self.rules = dict(ACUPOINT_LOCALIZATION_RULES)
        self._resolution_cache: Dict[Tuple[str, str], Dict[str, Any]] = {}

    def get_rule(self, point_code: str) -> Optional[AcupointLocalizationRule]:
        return self.rules.get(point_code)

    def resolve_point_location(
        self,
        point_code: str,
        side: str = "right",
    ) -> Optional[Dict[str, Any]]:
        """Evaluate rule for a point and compute its canonical 3D coordinates and normal."""
        cache_key = (point_code, side)
        if cache_key in self._resolution_cache:
            return dict(self._resolution_cache[cache_key])
        rule = self.get_rule(point_code)
        if not rule:
            return None

        pos: Optional[List[float]] = None
        norm: Optional[List[float]] = None

        # 1. LANDMARK_DEFINED directly on an authoritative landmark
        if rule.start_landmark_id and rule.start_landmark_id == rule.end_landmark_id:
            lm = self.registry.get_landmark(rule.start_landmark_id)
            if lm and not lm.verification_status.startswith("BLOCKED"):
                pos = list(lm.canonical_position)

        # 2. B_CUN_PROPORTIONAL interpolation between two landmarks
        elif rule.start_landmark_id and rule.end_landmark_id:
            lm_start = self.registry.get_landmark(rule.start_landmark_id)
            lm_end = self.registry.get_landmark(rule.end_landmark_id)

            if lm_start and lm_end and not lm_start.verification_status.startswith("BLOCKED") and not lm_end.verification_status.startswith("BLOCKED"):
                p0 = lm_start.canonical_position
                p1 = lm_end.canonical_position
                t = rule.proportional_fraction

                # Interpolate along chord
                pos = [
                    (1.0 - t) * p0[0] + t * p1[0],
                    (1.0 - t) * p0[1] + t * p1[1],
                    (1.0 - t) * p0[2] + t * p1[2],
                ]

        if pos is None:
            return None

        # Apply lateral B-cun offset if specified (for both single landmark and segment interpolations)
        if rule.lateral_offset_cun > 0.0:
            seg_key = rule.transverse_segment_id or ("SEG_BACK_INTERSCAPULAR" if rule.meridian_code == "BL" else "SEG_CHEST_BINIPPLE")
            metrics = self.cun_engine.calculate_segment_metrics()
            seg_metric = metrics.get(seg_key)
            cun_val = (seg_metric.mm_per_cun / 1000.0) if seg_metric else 0.020
            lat_dist = rule.lateral_offset_cun * (0.015 if rule.body_region == BodyRegion.LOWER_EXTREMITY else cun_val)
            if rule.body_region in (BodyRegion.TORSO, BodyRegion.HEAD_NECK):
                pos[0] = lat_dist

        # Apply bilateral side reflection if left side requested
        if side == "left":
            pos[0] = -abs(pos[0]) if abs(pos[0]) > 1e-6 else 0.0
        else:
            pos[0] = abs(pos[0]) if abs(pos[0]) > 1e-6 else 0.0

        # Normal vector calculation
        if getattr(rule, "surface_normal", None) is not None:
            nx, ny, nz = rule.surface_normal
            if abs(pos[0]) < 1e-6:
                norm = [0.0, ny, nz]
            elif side == "left":
                norm = [-abs(nx), ny, nz]
            else:
                norm = [abs(nx), ny, nz]
            nmag = math.sqrt(norm[0]*norm[0] + norm[1]*norm[1] + norm[2]*norm[2])
            if nmag > 1e-6:
                norm = [norm[0] / nmag, norm[1] / nmag, norm[2] / nmag]
        elif point_code == "KI1":
            norm = [-0.02941, -0.99237, -0.11970] if side == "right" else [0.02941, -0.99237, -0.11970]
        elif rule.body_region == BodyRegion.HEAD_NECK:
            # Radial outward normal from cranial center (0.0, 1.62, 0.0)
            c_y = 1.62
            rx, ry, rz = pos[0], pos[1] - c_y, pos[2]
            rlen = math.sqrt(rx*rx + ry*ry + rz*rz)
            if rlen > 1e-5:
                norm = [rx / rlen, ry / rlen, rz / rlen]
        elif rule.body_region == BodyRegion.TORSO:
            if pos[2] < 0:
                norm = [0.0, 0.0, -1.0]
            else:
                norm = [0.0, 0.0, 1.0]
        else:
            norm = [0.0, 0.0, 1.0]

        res_dict = {
            "point_code": point_code,
            "side": side,
            "canonical_position": (round(pos[0], 6), round(pos[1], 6), round(pos[2], 6)),
            "surface_normal": (round(norm[0], 4), round(norm[1], 4), round(norm[2], 4)),
            "quality_class": rule.quality_class,
            "fma_anchor": rule.fma_anchor,
            "skeletal_structure": rule.skeletal_structure,
            "localization_method": rule.localization_method.value,
            "who_reference": rule.who_reference,
            "tolerance_radius_mm": rule.tolerance_radius_mm,
            "uncertainty_mm": rule.uncertainty_mm,
            "is_posture_sensitive": rule.is_posture_sensitive,
        }
        self._resolution_cache[cache_key] = res_dict
        return dict(res_dict)
